<?= $this->extend('pos/layout') ?><?= $this->section('content') ?>
<section class="panel table-scroll"><table><caption class="sr-only">Sales ordered newest first</caption><thead><tr><th>Sale</th><th>Product</th><th>Customer</th><th>Staff</th><th>Quantity</th><th>Total</th><th>Date</th></tr></thead><tbody>
<?php foreach ($sales as $sale): ?><tr><td>#<?= esc($sale['id']) ?></td><td><?= esc($sale['product_name']) ?></td><td><?= esc($sale['customer_name'] ?? 'Walk-in / unassigned') ?></td><td><?= esc($sale['staff_name']) ?></td><td><?= esc($sale['quantity']) ?></td><td>₱<?= esc(number_format((float) $sale['total_price'], 2)) ?></td><td><?= esc($sale['created_at']) ?></td></tr><?php endforeach; ?>
